const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('shown');revealObserver.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
const form=document.querySelector('.contact-form');form.addEventListener('submit',event=>{event.preventDefault();let valid=true;const name=form.querySelector('#name'),email=form.querySelector('#email');[[name,name.value.trim().length>1],[email,/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)]].forEach(([input,ok])=>{input.closest('label').classList.toggle('invalid',!ok);input.setAttribute('aria-invalid',String(!ok));if(!ok)valid=false});if(valid){const success=form.querySelector('.form-success');success.classList.add('show');success.focus()}});form.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>input.closest('label').classList.remove('invalid')));document.querySelector('#year').textContent=new Date().getFullYear();
